// Résolution du lien réel du classeur depuis la page d'index.
// Le nom du fichier change à chaque parution (SIPRI-Milex-data-1949-2025_v1.2.xlsx,
// CPB-World-Trade-Monitor-<mois>.xlsx…) : la liaison déclare la page stable et un
// motif (regex, groupe 1 = lien). L'URL résolue est consignée dans l'item — elle
// fait partie de la trace d'audit du run.
const b = $json;
const runId = $('Ouvrir le run').first().json.run_id;
const mapping = typeof b.mapping === 'string' ? JSON.parse(b.mapping) : (b.mapping ?? {});
// Mode direct : sans motif_lien, url_base EST l'URL du fichier — résolution
// manuelle assumée (CPB : la page ne porte pas de lien dans son HTML,
// constaté le 17.08.2026 ; le veilleur relève l'URL du mois, la liaison la
// porte, la chaîne fait le reste). Semi-automatisé conforme au scénario B.
if (!mapping.motif_lien) {
  return { json: { ...b, mapping, url_fichier: b.url_base, run_id: runId, raw_ref: '/data/staging/' + b.indicator_id + '_run' + runId + '.xlsx' } };
}
const html = await this.helpers.httpRequest({ url: b.url_base, method: 'GET', headers: { 'User-Agent': 'Mozilla/5.0' } });
const texte = typeof html === 'string' ? html : JSON.stringify(html);
const m = texte.match(new RegExp(mapping.motif_lien, 'i'));
if (!m) throw new Error(b.indicator_id + ' : aucun lien ne correspond au motif sur ' + b.url_base);
let lien = m[1] ?? m[0];
if (lien.startsWith('//')) lien = 'https:' + lien;
else if (lien.startsWith('/')) {
  const origine = (b.url_base.match(/^https?:\/\/[^\/]+/) || [''])[0];
  if (!origine) throw new Error(b.indicator_id + ' : origine introuvable dans url_base');
  lien = origine + lien;
}
return { json: { ...b, mapping, url_fichier: lien, run_id: runId, raw_ref: '/data/staging/' + b.indicator_id + '_run' + runId + '.xlsx' } };

// Pivot large -> long, puis contrôles qualité déterministes.
// Les classeurs statistiques sont en format LARGE : une ligne par entité,
// une colonne par période. La liaison déclare la colonne d'entité, les
// entités retenues (et leur code de zone), et le motif des colonnes de
// période. NOTE DE DETTE : le bloc de contrôles est dupliqué du collecteur
// générique — divergence possible, consignée en note de rédaction.
// Fenêtre fonction de la PÉRIODICITÉ, alignée sur collecte_generique.json
// (§ 8.5, révision du 24.08.2026). Une fenêtre unique à trois ans ne laisse que
// trois points à une série annuelle — sous le seuil d'éligibilité de huit points
// de v_sante_secteur. Le défaut avait été corrigé dans le collecteur générique le
// 24.08 et SUBSISTAIT ICI : la même hypothèse écrite deux fois n'a été corrigée
// qu'une. Douzième occurrence du motif du § 12.6, dans sa variante duplication.
const FENETRE_ANNUELLE = '2014';
const FENETRE_INFRA_ANNUELLE = '2023';
const fenetreDe = periode => /^\d{4}$/.test(String(periode)) ? FENETRE_ANNUELLE : FENETRE_INFRA_ANNUELLE;
const SEUIL_VARIATION_ANORMALE = 200;
const lignes = $input.all();
const brutes = [];
const incidents = [];
const traces = [];

for (let i = 0; i < lignes.length; i++) {
  const r = lignes[i].json;
  let l;
  try { l = $('Résoudre le lien du classeur').itemMatching(i).json; }
  catch (e) { incidents.push('ligne ' + i + ' : liaison introuvable (' + e.message + ')'); continue; }
  const m = l.mapping ?? {};
  const ent = m.colonne_entite ? String(r[m.colonne_entite] ?? '').trim() : null;
  if (m.colonne_entite && !ent) continue;
  const retenues = Array.isArray(m.entites_retenues) ? m.entites_retenues : null;
  if (retenues && !retenues.includes(ent)) continue;
  const geo = (m.entites_geo && m.entites_geo[ent]) ? m.entites_geo[ent] : (ent ?? l.geo_defaut);
  const motifPeriode = new RegExp(m.motif_periode ?? '^\\d{4}$');
  for (const [col, brutVal] of Object.entries(r)) {
    if (!motifPeriode.test(col)) continue;
    let period = col;
    const mm = col.match(/^(\d{4})M(\d{2})$/i);
    if (mm) period = mm[1] + '-' + mm[2];
    if (m.periode_min && period < m.periode_min) continue;
    const val = Number(String(brutVal ?? '').replace(/[\s']/g, '').replace(',', '.'));
    if (!Number.isFinite(val)) continue;
    brutes.push({ indicator_id: l.indicator_id, run_id: l.run_id, period, geo, value: val, raw_ref: l.raw_ref });
  }
}

if (brutes.length === 0) {
  const exemples = lignes.slice(0, 3).map(x => Object.keys(x.json).slice(0, 12).join(','));
  incidents.push('AUCUNE observation extraite des classeurs — feuille, plage ou motifs à revoir. Clés vues sur les premières lignes : ' + (exemples.join(' | ') || 'aucune ligne'));
  return [{ json: { _aucune_observation: true, _bilan: { retenues: 0, ecartees: 0, indicateurs: [], incidents, traces } } }];
}

// Contrôles qualité — mêmes règles que le collecteur générique.
const retenuesL = [];
const ecartees = [];
const series = new Map();
for (const o of brutes) {
  const cle = o.indicator_id + '|' + o.geo;
  if (!series.has(cle)) series.set(cle, []);
  series.get(cle).push(o);
}
for (const [, liste] of series) {
  liste.sort((a, b) => String(a.period).localeCompare(String(b.period)));
  let precedente = null;
  for (const o of liste) {
    const motifs = [];
    if (!Number.isFinite(o.value)) motifs.push('valeur non numérique');
    if (!/^\d{4}(-(\d{2}|T\d|S\d))?$/.test(String(o.period))) motifs.push('format de période invalide');
    if (String(o.period).slice(0, 4) < fenetreDe(o.period))
      motifs.push(`hors fenêtre d'historique (plancher ${fenetreDe(o.period)} pour cette périodicité)`);
    if (o.value < 0) motifs.push('valeur négative');
    if (precedente !== null && precedente !== 0) {
      const variation = Math.abs((o.value - precedente) / precedente * 100);
      // Exemption « retour dans la plage » : proposée puis REFUSÉE par l'étudiant
      // le 25.08.2026, même motif que dans le collecteur générique. La règle
      // reste stricte.
      if (variation > SEUIL_VARIATION_ANORMALE) motifs.push('variation anormale de ' + variation.toFixed(1) + ' %');
    }
    if (motifs.length) { ecartees.push({ indicateur: o.indicator_id, periode: o.period, geo: o.geo, motifs }); }
    else { retenuesL.push(o); }
    // La précédente avance TOUJOURS, même sur un point écarté : geler la
    // référence sur le dernier point retenu fait tomber toute la suite de la
    // série en cascade. Bogue constaté le 25.08 sur le collecteur générique
    // (A5 arrêté à 2020-04 par le choc COVID), corrigé ici à l'identique.
    precedente = o.value;
  }
}

if (retenuesL.length === 0) {
  incidents.push('toutes les observations extraites ont été écartées : ' + JSON.stringify(ecartees.slice(0, 3)));
  return [{ json: { _aucune_observation: true, _bilan: { retenues: 0, ecartees: ecartees.length, indicateurs: [], incidents, traces } } }];
}

const bilan = {
  retenues: retenuesL.length,
  ecartees: ecartees.length,
  indicateurs: [...new Set(retenuesL.map(o => o.indicator_id))].sort(),
  detail_ecartees: ecartees.slice(0, 20),
  incidents,
  traces
};
return retenuesL.map(o => ({ json: { ...o, _bilan: bilan } }));
